// HEC IELTS Speaking & Listening, Year 1, Term 1 (Talk about my world): class plays for
// Sun Class (grades 8-10). Original scripts by the school; no test material, no promise of a band.
import type { Play, PlayLine } from "@/lib/lessonDecks/plays";

const r = (role: string, text: string, d?: string): PlayLine => (d ? { role, text, do: d } : { role, text });
// A group line pinned to one member (the child who holds the keys, the phone, the secret).
const pin = (role: string, member: number, text: string, d?: string): PlayLine => ({ role, text, member, ...(d ? { do: d } : {}) });
const all = (role: string, text: string, d?: string): PlayLine => ({ role, text, all: true, ...(d ? { do: d } : {}) });
const st = (stage: string, cond?: string): PlayLine => (cond ? { stage, if: cond } : { stage });
const ev = (everyone: string, d?: string): PlayLine => (d ? { everyone, do: d } : { everyone });
// Script, then key words, then no script at all: the last round is always the students' own words.
const rh = (cards: string, noScript: string) => [
  { round: "Read-through with scripts", minutes: 8, how: "Read the play aloud with parts, once through, standing where the stage directions say. Hidden things stay hidden: nobody looks at another character's phone, card or box. Then the teacher's one-minute fix." },
  { round: "Key-word cards", minutes: 6, how: `Scripts down. Each part keeps a card with key words only, and the play runs faster, in the 4/3/2 spirit: same story, less time. ${cards} Then a second one-minute fix.` },
  { round: "No script, improvised ending", minutes: 11, how: `Every paper away. Run only the last scene from memory, in your own words and keeping the frames (about four minutes), then play the improvised scene (about seven). ${noScript}` },
];
const mk = (n: number, p: Omit<Play, "id" | "course" | "level" | "unit" | "band">): Play => ({
  id: `hec-ielts-y1-t1-p${n}`, course: "hec-ielts-sl", level: 1, unit: 1, band: "13-16", ...p,
});

